import java.util.Scanner;

public class Main {
    static final int N = 100;
    static final int D = 31;
    static final long MOD = 1000000007L;

    static int d_value, position;
    static int[] array_a = new int[N];
    static long num;
    static Mat[] matrices = new Mat[N];

    static class Mat {
        long[][] mat = new long[D + 1][D + 1];

        Mat() {
            for (int i = 0; i <= d_value; i++) {
                for (int j = 0; j <= d_value; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        Mat multiply(Mat other) {
            Mat res = new Mat();
            for (int i = 0; i <= d_value; i++) {
                for (int j = 0; j <= d_value; j++) {
                    for (int k = 0; k <= d_value; k++) {
                        res.mat[i][j] = (res.mat[i][j] + this.mat[i][k] * other.mat[k][j]) % MOD;
                    }
                }
            }
            return res;
        }
    }

    static Mat shift(int shift_val) {
        shift_val = (shift_val + d_value) % d_value;
        Mat m = new Mat();
        for (int i = 0; i < d_value; i++) {
            m.mat[i][(i + shift_val) % d_value] = 1;
        }
        m.mat[d_value][d_value] = 1;
        return m;
    }

    static void setup() {
        matrices[0] = new Mat();
        for (int i = 1; i < d_value; i++) {
            matrices[0].mat[i][i] = 1;
        }
        matrices[0].mat[d_value][0] = 1;
        matrices[0].mat[d_value][d_value] = 2;
        matrices[0].mat[0][d_value] = -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        num = sc.nextLong();
        d_value = sc.nextInt();

        long tempNum = num;
        position = 0;
        while (tempNum > 0) {
            array_a[position] = (int)(tempNum % d_value);
            tempNum /= d_value;
            position++;
        }

        setup();

        for (int i = 1; i < position; i++) {
            matrices[i] = shift(0);
            for (int j = 0; j < d_value; j++) {
                matrices[i] = matrices[i].multiply(matrices[i - 1]).multiply(shift(1));
            }
        }

        Mat result = shift(0);
        for (int i = position - 1; i >= 0; i--) {
            for (int j = 0; j < array_a[i]; j++) {
                result = result.multiply(matrices[i]).multiply(shift(1));
            }
        }

        System.out.println((result.mat[d_value][d_value] + MOD) % MOD);
        sc.close();
    }
}
